do $ctrl$
declare
  v_total integer;
begin
  select count(*) into v_total from public.prompts where catalog_version = 'v2.1';
  if v_total < 320 then
    raise exception 'Lot 9 incomplet : % raccourcis importes au lieu de 320.', v_total;
  end if;
end $ctrl$;

drop table lot_prompts;
